function sprite(type,name,extra=''){const a=atlas[type],id=(type==='racer'?racerIds:iconIds)[name],w=a.w/a.cols,h=a.h/a.rows;const x=id%a.cols*w,y=Math.floor(id/a.cols)*h,clip='spriteClip'+(++spriteUid);return `<svg class="sprite ${extra}" viewBox="${x} ${y} ${w} ${h}" aria-hidden="true"><defs><clipPath id="${clip}"><rect x="${x}" y="${y}" width="${w}" height="${h}"/></clipPath></defs><image clip-path="url(#${clip})" href="${a.file}" x="0" y="0" width="${a.w}" height="${a.h}"/></svg>`}
